// Selectivity matrix — every QC-passing AssayResult, joined to its
// compound + target. This is the data a Phase 5 grouped-bar chart
// would consume (one bar per (compound, target) IC50; group by
// compound, colour by target).

USING "urn:eigenius:demo:assay:AssayResult"

MATCH AssayResult(?r) {
    "urn:eigenius:demo:assay:compound":         ?c,
    "urn:eigenius:demo:assay:target":           ?t,
    "urn:eigenius:demo:assay:ic50_nm":          ?ic50,
    "urn:eigenius:demo:assay:ci_low_nm":        ?ci_low,
    "urn:eigenius:demo:assay:ci_high_nm":       ?ci_high,
    "urn:eigenius:demo:assay:replicate_count":  ?n,
    "urn:eigenius:demo:assay:passed_qc":        ?qc
},
?c { "urn:eigenius:demo:assay:compound_id": ?compound_id },
?t { "urn:eigenius:demo:assay:target_name": ?target_name }
WHERE ?qc = true
RETURN [] {
    compound: ?compound_id,
    target:   ?target_name,
    ic50_nm:  ?ic50,
    ci_low:   ?ci_low,
    ci_high:  ?ci_high,
    n:        ?n
}
ORDER BY ?compound_id

// QC pass-rate by protocol. The chart Phase 5 would render: a donut
// or stacked bar chart showing how many results passed/failed per
// protocol — TR-FRET runs the very-weak EGFR off-target measurements
// and absorbs all the QC failures, while Kinase-Glo / ADP-Glo are
// clean.

USING "urn:eigenius:demo:assay:AssayResult"

MATCH AssayResult(?r) {
    "urn:eigenius:demo:assay:protocol":   ?p,
    "urn:eigenius:demo:assay:passed_qc":  ?qc
},
?p { "urn:eigenius:demo:assay:protocol_name": ?protocol_name }
RETURN [] {
    protocol: ?protocol_name,
    qc:       ?qc
}
ORDER BY ?protocol_name

cells.query:
// IC50 selectivity profile — grouped bar chart. One group per
// compound; one bar per target within each group; bar height is
// IC50 in nM (lower = more potent). CDK-selective compounds show
// short bars on their preferred target and tall bars on EGFR; the
// EGFR-selective EIG_0203 shows the inverse.

USING "urn:eigenius:demo:assay:AssayResult"
MATCH AssayResult(?r) {
    "urn:eigenius:demo:assay:compound":   ?c,
    "urn:eigenius:demo:assay:target":     ?t,
    "urn:eigenius:demo:assay:ic50_nm":    ?ic50,
    "urn:eigenius:demo:assay:passed_qc":  ?qc
},
?c { "urn:eigenius:demo:assay:compound_id": ?compound_id },
?t { "urn:eigenius:demo:assay:target_name": ?target_name }
WHERE ?qc = true
RETURN [] {
    compound: ?compound_id,
    target:   ?target_name,
    ic50_nm:  ?ic50
}
ORDER BY ?compound_id

// QC pass / fail breakdown across all 24 results. Donut showing how
// QC failures concentrate on the very-weak EGFR off-target
// measurements (which all run on the TR-FRET protocol).

USING "urn:eigenius:demo:assay:AssayResult"
MATCH AssayResult(?r) {
    "urn:eigenius:demo:assay:passed_qc": ?qc
}
GROUP BY ?qc
RETURN [] {
    status: ?qc,
    count:  COUNT(?r)
}

// Mean IC50 per target across QC-passing measurements. Vertical-bar
// chart — single series, one bar per target. CDK targets cluster at
// low IC50 (most compounds are CDK-active); EGFR averages much
// higher because only EIG_0203 hits it.

USING "urn:eigenius:demo:assay:AssayResult"
MATCH AssayResult(?r) {
    "urn:eigenius:demo:assay:target":     ?t,
    "urn:eigenius:demo:assay:ic50_nm":    ?ic50,
    "urn:eigenius:demo:assay:passed_qc":  ?qc
},
?t { "urn:eigenius:demo:assay:target_name": ?target_name }
WHERE ?qc = true
GROUP BY ?target_name
RETURN [] {
    target:    ?target_name,
    mean_ic50: AVG(?ic50)
}
ORDER BY ?target_name

// Compounds ranked by molecular weight. Horizontal-bar chart — bar
// labels along the y-axis, bar length is MW in g/mol. Sorted
// descending so the heaviest scaffold (quinazoline) tops the list.

USING "urn:eigenius:demo:assay:Compound"
MATCH Compound(?c) {
    "urn:eigenius:demo:assay:compound_id":      ?compound_id,
    "urn:eigenius:demo:assay:molecular_weight": ?mw
}
RETURN [] {
    compound: ?compound_id,
    mw:       ?mw
}
ORDER BY ?mw DESC

// IC50 trajectory across CDK targets, one line per compound. Lines
// that stay flat-and-low (EIG_0291) indicate pan-CDK activity; lines
// with deep notches (EIG_0042 at CDK2, EIG_0117 at CDK4) flag
// selectivity. EGFR is excluded so the CDK story isn't crushed by
// the off-target IC50 scale.

USING "urn:eigenius:demo:assay:AssayResult"
MATCH AssayResult(?r) {
    "urn:eigenius:demo:assay:compound":   ?c,
    "urn:eigenius:demo:assay:target":     ?t,
    "urn:eigenius:demo:assay:ic50_nm":    ?ic50,
    "urn:eigenius:demo:assay:passed_qc":  ?qc
},
?c { "urn:eigenius:demo:assay:compound_id": ?compound_id },
?t { "urn:eigenius:demo:assay:target_name":   ?target_name,
     "urn:eigenius:demo:assay:target_family": ?fam }
WHERE ?qc = true AND ?fam = "CDK"
RETURN [] {
    compound: ?compound_id,
    target:   ?target_name,
    ic50_nm:  ?ic50
}
ORDER BY ?compound_id, ?target_name

// Mean IC50 by scaffold class across CDK targets — area chart with
// one series per scaffold (pyrimidine / indazole / quinazoline /
// pyrazolopyrimidine). Reveals which scaffold family is most potent
// on which kinase. Pyrazolopyrimidine (EIG_0291) traces a near-flat
// pan-CDK profile; quinazoline (EIG_0203) sits well above the others
// across all CDKs.

USING "urn:eigenius:demo:assay:AssayResult"
MATCH AssayResult(?r) {
    "urn:eigenius:demo:assay:compound":   ?c,
    "urn:eigenius:demo:assay:target":     ?t,
    "urn:eigenius:demo:assay:ic50_nm":    ?ic50,
    "urn:eigenius:demo:assay:passed_qc":  ?qc
},
?c { "urn:eigenius:demo:assay:scaffold_class": ?scaffold },
?t { "urn:eigenius:demo:assay:target_name":   ?target_name,
     "urn:eigenius:demo:assay:target_family": ?fam }
WHERE ?qc = true AND ?fam = "CDK"
GROUP BY ?scaffold, ?target_name
RETURN [] {
    scaffold:  ?scaffold,
    target:    ?target_name,
    mean_ic50: AVG(?ic50)
}
ORDER BY ?scaffold, ?target_name

