// Full ontology topology graph for the assay namespace. Fetches the
// layer chain with class / property / institution nodes (no per-
// resource nodes — that'd be 30+ extra dots), filters out everything
// outside the assay namespace, and routes the result to xyflow via
// the auto-renderer.
//
// Each kind gets its own colour: classes blue, properties green,
// institutions purple. Edges are coloured by relationship
// (`is_a` / `subclass_of` / `requires` / `recommends` / `property_ref`).

const topo = await eigen.layerTopology({ includeResources: false });

const PREFIX = "urn:eigenius:demo:assay:";
const keep = new Set();
for (const n of topo.nodes) {
  if (n.id.startsWith(PREFIX)) keep.add(n.id);
}

return {
  nodes: topo.nodes.filter((n) => keep.has(n.id)),
  edges: topo.edges.filter((e) => keep.has(e.source) && keep.has(e.target)),
};
